<script setup lang="ts">
import{ref,watch}from'vue';import MPopover from '../MPopover.vue';import MColorPickerPanel from './MColorPickerPanel.vue';import MValueBridge from './MValueBridge.vue';import{parseHex}from'./color';import type{MColorPickerProps}from'./types';import{useReferenceConfig}from'./locale';
const props=defineProps<MColorPickerProps>();const emit=defineEmits<{ 'update:modelValue':[value:string] }>();const open=ref(false);const{t}=useReferenceConfig();watch(()=>[props.disabled,props.readonly],()=>{if(props.disabled||props.readonly)open.value=false;});
</script>
<template><div class="ui-ri"><span class="ui-ri__label">{{label}}</span><div class="ui-ri__row"><MPopover v-model="open" :label="label" :trigger-label="label" :disabled="disabled||readonly"><template #trigger><span class="ui-ri-color__chip" aria-hidden="true" :style="{backgroundColor:parseHex(modelValue)?modelValue:'transparent'}"></span>{{modelValue||t('color.choose','选择颜色')}}</template><MColorPickerPanel :model-value="modelValue" :label="label" :alpha="alpha" :presets="presets" :disabled="disabled" :readonly="readonly" @update:model-value="emit('update:modelValue',$event)"/></MPopover><button type="button" class="ui-ri__button" :disabled="disabled||readonly||!modelValue" @click="emit('update:modelValue','')">{{t('clear','清空')}}</button></div><MValueBridge v-bind="props" :values="modelValue?[modelValue]:[]" :error="modelValue&&!parseHex(modelValue)?t('color.hexInvalid','请输入有效 HEX 色值。'):''"/></div></template>
<style scoped>.ui-ri-color__chip{display:inline-block;width:20px;height:20px;border:1px solid var(--ui-color-metal)}</style>
